<?php $title='Auftrag '.$order['orderNumber'];$contentClass='content-wide';$labels=['open'=>'Offen','in_progress'=>'In Bearbeitung','completed'=>'Abgeschlossen','invoiced'=>'Abgerechnet'];$next=['open'=>'in_progress','in_progress'=>'completed','completed'=>'invoiced']; ?>
<div id="order-detail" data-id="<?= $escape($order['id']) ?>" data-status="<?= $escape($order['status']) ?>" data-csrf="<?= $escape($csrfToken) ?>">
 <p class="breadcrumb"><a href="/orders">← Auftragsübersicht</a></p><section class="card"><div class="page-heading"><div><h1><?= $escape($order['orderNumber'].' · '.$order['title']) ?></h1><p><span class="status-badge status-<?= $escape($order['status']) ?>"><?= $escape($labels[$order['status']]) ?></span> · <?= $escape($order['orderType']==='offer'?'Angebotsauftrag':'Regieauftrag') ?></p></div><?php if(isset($next[$order['status']])): ?><button class="button" data-next-status="<?= $escape($next[$order['status']]) ?>" data-icon="refresh-cw">Status: <?= $escape($labels[$next[$order['status']]]) ?></button><?php endif; ?></div><div class="project-facts"><div><span>Kunde</span><strong><?= $escape($order['customerName']) ?></strong></div><div><span>Projekt</span><strong><?= $escape($order['projectName']??'Ohne Projekt') ?></strong></div><div><span>Auftragsdatum</span><strong><?= $escape((new DateTimeImmutable($order['orderDate']))->format('d.m.Y')) ?></strong></div></div><?php if($order['description']!==''): ?><p><?= nl2br($escape($order['description'])) ?></p><?php endif; ?></section>
 <?php if($order['orderType']==='offer'): ?><section class="card"><h2>Unveränderliche Auftragsgrundlage</h2><p>Angebot <?= $escape($order['sourceOfferNumber']) ?><?= $order['sourceRevision']>0?' · Revision '.$escape((string)$order['sourceRevision']):'' ?></p><a class="button button-light" data-icon="eye" href="/offers/<?= $escape(rawurlencode($order['sourceOfferId'])) ?>">Angebotsstand anzeigen</a><p class="muted"><?= $escape((string)count($order['basis']['nodes']??[])) ?> Hauptelemente wurden als Auftragsgrundlage archiviert.</p></section><?php else: ?><section class="notice">Direkter Regieauftrag ohne Angebotsgrundlage. Rapporte und Ist-Erfassung folgen in späteren Phasen.</section><?php endif; ?>
 <section class="card"><h2>Statusverlauf</h2><div class="service-list"><?php foreach($order['history'] as $h): ?><div class="service-list-item"><strong><?= $escape($labels[$h['new_status']]??$h['new_status']) ?></strong><span class="muted"><?= $escape((new DateTimeImmutable($h['changed_at']))->format('d.m.Y H:i')) ?></span></div><?php endforeach; ?></div></section>
